#!/usr/bin/env python3
import json,html,hashlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def read(p,default=None):return json.loads(p.read_text()) if p.exists() else default
places=[]
for folder in sorted((ROOT/'places').iterdir()):
 d=read(folder/'research.json'); supplement=read(folder/'verified-research.json',{});assets=[]
 for key,title in [('hero','Portada')]+[(a.get('image_key',f'attraction-{i+1:02}'),a['name']) for i,a in enumerate(d['attractions'])]:
  ref=read(folder/'references'/f'{key}.json',{});original=folder/'references'/f'{key}.jpg';output=folder/'images'/f'{key}-1200.webp'
  assets.append({'key':key,'title':title,'original':str(original.relative_to(ROOT)) if original.exists() else None,'output':str(output.relative_to(ROOT)) if output.exists() else None,'hash':hashlib.sha256(output.read_bytes()).hexdigest() if output.exists() else None,'source':ref.get('source_url') or ref.get('source_page'),'license':ref.get('license'),'author':ref.get('author_html') or ref.get('author'),'caption':ref.get('title'),'manifest':read(folder/'images'/f'{key}.manifest.json',{})})
 mapped=read(folder/'osm-discovery.json',{}).get('candidates',[])
 places.append({'research':d,'supplement':supplement,'assets':assets,'mapped':mapped})
data=json.dumps(places,ensure_ascii=False).replace('</','<\\/')
page='''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>16 destinos · Revisión editorial</title><style>
*{box-sizing:border-box}body{margin:0;color:#24332c;background:#f6f3ed;font:16px/1.5 system-ui}header{padding:20px 4%;background:#fff;border-bottom:1px solid #ddd7ca}h1{font-size:25px;margin:0}p{margin:8px 0}.muted{color:#66736c;font-size:14px}nav{display:flex;flex-wrap:wrap;gap:8px;padding:16px 4%;position:sticky;top:0;background:#f6f3edf5;z-index:2;border-bottom:1px solid #ddd}button,select{font:inherit;border:1px solid #b7c1b7;background:#fff;border-radius:8px;padding:9px 14px;cursor:pointer}button.active{background:#315c46;color:white}main{max-width:1320px;margin:auto;padding:25px}section{background:white;border:1px solid #d9ded7;border-radius:12px;padding:20px;margin:20px 0}h2,h3{margin:0 0 10px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:16px}figure{margin:0}img{display:block;width:100%;aspect-ratio:3/2;object-fit:contain;background:#e9ece8;border-radius:7px}figcaption{padding:8px;font-size:14px}.empty{display:grid;place-items:center;min-height:180px;background:#f4f3ef;color:#766c5b;border:1px dashed #b6afa2}.actions{display:flex;gap:8px;align-items:center;margin-top:14px;flex-wrap:wrap}textarea{width:100%;font:inherit;border:1px solid #bdc7bd;border-radius:6px;padding:10px;min-height:65px;margin-top:10px}a{color:#245944}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:9px;border-bottom:1px solid #ddd;text-align:left}.scroll{overflow:auto}.badge{font-size:13px;padding:4px 8px;background:#eee6d6;border-radius:5px}.approve{background:#dcebe0}.reject{background:#f4deda}.status{margin-left:auto}.controls{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.note{border-left:3px solid #d69947;padding-left:12px}summary{cursor:pointer}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.5 system-ui}.stats{display:flex;gap:15px;flex-wrap:wrap;margin:10px 0}@media(max-width:700px){.pair{grid-template-columns:1fr}main{padding:12px}section{padding:12px}nav{position:static}h1{font-size:21px}}
</style><header><h1>16 destinos · Revisión editorial</h1><p>Portadas, qué conocer, experiencias y negocios. Preparación independiente; no publicado.</p><p class="muted">Las aprobaciones se guardan en este navegador. Exporta la revisión para conservarlas fuera de él. Cambiar una imagen invalida únicamente su aprobación anterior.</p><div class="controls"><button onclick="download()">Exportar aprobaciones y comentarios</button><label>Importar revisión <input type="file" accept="application/json" onchange="importReview(this)"></label></div><div id="stats" class="stats"></div></header><nav><button onclick="step(-1)">← Anterior</button><select id="place" onchange="pick(this.value)"></select><button onclick="step(1)">Siguiente →</button><button id="images" onclick="setTab('images')">Imágenes</button><button id="content" onclick="setTab('content')">Contenido y ubicación</button><button id="business" onclick="setTab('business')">Negocios</button></nav><main id="main"></main><script>
const places=__DATA__;let index=0,tab='images';const storageKey='el-review-16-20261104';let review={};try{review=JSON.parse(localStorage.getItem(storageKey)||'{}')}catch(e){}const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const select=document.getElementById('place');places.forEach((p,i)=>select.add(new Option((i+1)+'. '+p.research.name,i)));function pick(i){index=Number(i);location.hash=places[index].research.slug;render()}function step(n){pick((index+n+places.length)%places.length)}function setTab(t){tab=t;render()}function key(a){return places[index].research.slug+':'+a.key+':'+(a.hash||'no-image')}function persist(){try{localStorage.setItem(storageKey,JSON.stringify(review))}catch(e){alert('No se pudo guardar en este navegador. Exporta la revisión.')}}function mark(k,s){review[k]={...(review[k]||{}),status:s,at:new Date().toISOString()};persist();render()}function comment(k,t){review[k]={...(review[k]||{}),comment:t};persist()}
function geo(g){if(!g||g.latitude==null||g.longitude==null)return '<p class="note">Ubicación precisa pendiente de confirmar. No se ha colocado un punto inventado.</p>';const lat=Number(g.latitude),lon=Number(g.longitude);return `<p><b>${esc(g.label||g.name||g.site_name||'Punto documentado')}</b><br>${lat.toFixed(6)}, ${lon.toFixed(6)} · <a target="_blank" rel="noopener" href="https://www.openstreetmap.org/?mlat=${lat}&mlon=${lon}#map=15/${lat}/${lon}">Ver ubicación</a> ${g.source_url?`· <a target="_blank" rel="noopener" href="${esc(g.source_url)}">Fuente</a>`:''}</p><details><summary>Alcance de la coordenada</summary><p>${esc(g.point_kind||g.kind||g.coordinate_kind||'Referencia cartográfica; acceso no verificado')}</p></details>`}
function render(){const p=places[index],d=p.research;select.value=index;['images','content','business'].forEach(t=>document.getElementById(t).className=t===tab?'active':'');const ready=places.flatMap(p=>p.assets).filter(a=>a.output).length,total=places.flatMap(p=>p.assets).length;document.getElementById('stats').innerHTML=`<b>16 destinos</b><span>${ready} de ${total} imágenes preparadas</span><span>${places.reduce((n,p)=>n+(p.research.businesses||[]).length,0)} fichas de negocios para revisar</span>`;let out=`<h2>${esc(d.name)}</h2><p>${esc(d.intro_draft_es)}</p>`;
if(tab==='images')for(const a of p.assets){const k=key(a),v=review[k]||{};out+=`<section><h3>${esc(a.title)}</h3><div class="pair"><figure>${a.original?`<img loading="lazy" src="${esc(a.original)}">`:'<div class="empty">Referencia específica pendiente de selección</div>'}<figcaption>Fotografía de referencia ${a.source?`· <a target="_blank" rel="noopener" href="${esc(a.source)}">Fuente y autoría</a>`:''}<br>${esc(a.license||'')}<br>${esc((a.author||'').replace(/<[^>]*>/g,''))}</figcaption></figure><figure>${a.output?`<img loading="lazy" src="${esc(a.output)}">`:'<div class="empty">Ilustración aún no preparada; no es un activo aprobado</div>'}<figcaption>${a.manifest.kind==='licensed_photograph'?'Fotografía licenciada conservada para fidelidad':'Ilustración propuesta'} · WebP · ${a.hash?'Versión '+a.hash.slice(0,10):'Sin versión'}</figcaption></figure></div><details><summary>Notas de fidelidad y uso</summary><pre>${esc(JSON.stringify({revision:a.manifest.qa_notes||a.manifest.visual_review_notes||a.manifest.visual_review||null,uso:a.manifest.reference?.publication_rights_status||a.manifest.reference?.publication_blocker||a.manifest.publication_blocker||null},null,2))}</pre></details><div class="actions">${a.output?`<button class="approve" onclick='mark(${JSON.stringify(k)},"approved")'>Aprobar esta versión</button><button class="reject" onclick='mark(${JSON.stringify(k)},"changes_requested")'>Pedir ajuste</button>`:''}<span class="badge status">${esc(v.status==='approved'?'Aprobada por ti':v.status==='changes_requested'?'Con ajustes solicitados':'Pendiente de revisión')}</span></div><textarea placeholder="Comentario sobre encuadre, identidad o composición" onchange='comment(${JSON.stringify(k)},this.value)'>${esc(v.comment||'')}</textarea></section>`}
if(tab==='content'){out+=`<section><h3>Por qué visitarlo</h3><ul>${(d.why_visit_es||[]).map(x=>'<li>'+esc(x)+'</li>').join('')}</ul>${d.history_draft_es?`<h3>Contexto</h3><p>${esc(d.history_draft_es)}</p>`:''}<h3>Punto de referencia del destino</h3>${geo(d.geolocation)}</section>`;for(const a of d.attractions)out+=`<section><h3>${esc(a.name)}</h3><p>${esc(a.description_es||'')}</p>${a.current_access||a.access_note||a.publication_caution?`<p class="note">${esc(a.access_note||a.publication_caution||a.current_access)}</p>`:''}${geo(a.geolocation)}<a href="${esc(a.source_url)}" target="_blank" rel="noopener">Fuente documental</a></section>`;out+='<section><h3>Experiencias con oferta documentada</h3>';for(const e of d.experiences)out+=`<h4>${esc(e.name)}</h4><p>${esc(e.description_es||e.public_description_es||e.notes||'')}</p>${geo(e.geolocation)}<p class="muted">Evidencia interna: ${esc(e.operator_evidence||e.operator||'')} · <a href="${esc(e.source_url||e.offer_url||'')}" target="_blank" rel="noopener">Oferta</a></p>`;out+='</section>';if(Object.keys(p.supplement).length)out+=`<section><details><summary>Investigación complementaria y verificaciones</summary><pre>${esc(JSON.stringify(p.supplement,null,2))}</pre></details></section>`}
if(tab==='business'){out+='<section><p class="note">Fichas descubiertas en fuentes públicas. No implica negocio verificado, aliado, anunciante ni funcionamiento confirmado. Las coordenadas cartográficas identifican un sitio; no garantizan la entrada.</p><div class="scroll"><table><thead><tr><th>Nombre</th><th>Categoría</th><th>Coordenadas</th><th>Fuente</th></tr></thead><tbody>';for(const b of (d.businesses||[]))out+=`<tr><td>${esc(b.name)}</td><td>${esc(b.category)}</td><td>${b.geolocation?esc(b.geolocation.latitude)+', '+esc(b.geolocation.longitude):'Ubicación precisa pendiente'}</td><td><a target="_blank" rel="noopener" href="${esc(b.source_url)}">Consultar</a></td></tr>`;out+='</tbody></table></div></section>';out+=`<section><details><summary>Fuentes, contactos y estado de cada ficha</summary><pre>${esc(JSON.stringify(d.businesses,null,2))}</pre></details></section>`}document.getElementById('main').innerHTML=out;}
function download(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({batch:'2026-11-04-16',exported_at:new Date().toISOString(),review},null,2)],{type:'application/json'}));a.download='revision-16-destinos.json';a.click();URL.revokeObjectURL(a.href)}async function importReview(input){try{const data=JSON.parse(await input.files[0].text());if(data.batch!=='2026-11-04-16'||!data.review)throw Error('Lote incorrecto');review={...review,...data.review};persist();render()}catch(e){alert('No se pudo importar: '+e.message)}}const initial=places.findIndex(p=>p.research.slug===location.hash.slice(1));if(initial>=0)index=initial;render();
</script></html>'''
(ROOT/'review.html').write_text(page.replace('__DATA__',data));print('review.html',len(places),'places',sum(bool(a['output']) for p in places for a in p['assets']),'images')
